extra_css:
.lk-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:16px;margin:12px 0 24px}
.lk-opt{border:1px solid var(--color-border,#8886);padding:16px;margin:0 0 32px}
.lk-opt h3{margin:0 0 4px}.lk-meta{margin:0 0 12px;opacity:.85}
.lk-tag{display:inline-block;font-size:.8em;padding:1px 6px;border:1px solid currentColor;margin-left:6px}
.lk-win{font-family:ui-monospace,'Cascadia Mono','SF Mono',Menlo,Consolas,'Liberation Mono',monospace;font-size:13px;line-height:1.5;background:var(--t-page);color:var(--t-text);border:1px solid var(--t-border);border-radius:var(--t-r);overflow:hidden}
.lk-bar{display:flex;align-items:center;gap:6px;padding:6px 10px;background:var(--t-surface);border-bottom:1px solid var(--t-border);color:var(--t-muted);font-size:12px}
.lk-dot{width:10px;height:10px;border-radius:50%;border:1px solid var(--t-border)}
.lk-body{padding:12px;display:grid;gap:10px}
.lk-h{font-size:17px;font-weight:700;margin:0;color:var(--t-text)}
.lk-sub{color:var(--t-muted);margin:0;font-size:12px}
.lk-strip{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:6px 8px;background:var(--t-surface);border:1px solid var(--t-border);border-radius:var(--t-r)}
.lk-prog{flex:1 1 80px;height:6px;background:var(--t-sel);min-width:60px}.lk-prog i{display:block;height:100%;width:62%;background:var(--t-primary)}
.lk-card{background:var(--t-surface);border:1px solid var(--t-border);border-radius:var(--t-r);padding:10px;position:relative}
.lk-row{display:flex;justify-content:space-between;gap:8px;padding:3px 4px;flex-wrap:wrap}
.lk-row.sel{background:var(--t-sel)}
.lk-k{color:var(--t-muted)}
.t-done{color:var(--t-done)}.t-note{color:var(--t-note)}.t-needs{color:var(--t-needs)}.t-problem{color:var(--t-problem)}
.lk-in{display:block;width:100%;box-sizing:border-box;min-height:36px;padding:6px 8px;background:var(--t-page);color:var(--t-text);border:1px solid var(--t-primary);border-radius:var(--t-r);box-shadow:0 0 0 1px var(--t-primary),0 0 8px color-mix(in srgb,var(--t-primary) 50%,transparent)}
.lk-caret{display:inline-block;width:.6em;height:1.1em;vertical-align:text-bottom;background:var(--t-primary);animation:lkb 1s steps(1) infinite}
@keyframes lkb{50%{opacity:0}}@media (prefers-reduced-motion:reduce){.lk-caret{animation:none}}
.lk-acts{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap}
.lk-btn{min-height:36px;padding:6px 14px;border:1px solid var(--t-border);background:transparent;color:var(--t-text);border-radius:var(--t-r);font:inherit;font-weight:600}
.lk-btn.p{background:var(--t-primary);color:var(--t-onprimary);border-color:var(--t-primary)}
.lk-label{font-weight:600;font-size:12px;margin:0 0 3px}
.lk-sw{display:flex;flex-wrap:wrap;gap:4px;margin-top:8px}.lk-sw span{width:22px;height:22px;border:1px solid #8886}
.m-panes .lk-card{padding-top:14px;margin-top:6px}.m-panes .lk-card>.lk-ttl{position:absolute;top:-0.75em;left:10px;padding:0 6px;background:var(--t-page);color:var(--t-primary);font-weight:700}
.m-panes .lk-card .lk-row.sel{background:var(--t-primary);color:var(--t-onprimary)}.m-panes .lk-card .lk-row.sel *{color:var(--t-onprimary)}
.m-panes .lk-keys{display:flex;flex-wrap:wrap;gap:10px;padding:4px 8px;background:var(--t-surface);border-top:1px solid var(--t-border);font-size:12px}.m-panes .lk-keys b{background:var(--t-sel);color:var(--t-primary);padding:0 4px}
.m-panes .lk-card{background:var(--t-page)}
.m-charm .lk-card,.m-charm .lk-strip{border-width:1px;border-color:var(--t-border)}.m-charm .lk-h{color:var(--t-primary)}.m-charm .lk-body{gap:14px;padding:16px}
.m-charm .lk-pill{display:inline-block;padding:0 8px;border-radius:999px;background:var(--t-sel)}
.m-powerline .lk-pl{display:flex;flex-wrap:wrap;font-weight:700;font-size:12px}.m-powerline .lk-pl span{padding:3px 10px;background:var(--t-sel);color:var(--t-text);clip-path:polygon(0 0,calc(100% - 8px) 0,100% 50%,calc(100% - 8px) 100%,0 100%,8px 50%)}
.m-powerline .lk-pl span:first-child{background:var(--t-primary);color:var(--t-onprimary);clip-path:polygon(0 0,calc(100% - 8px) 0,100% 50%,calc(100% - 8px) 100%,0 100%)}
.m-powerline .lk-card>.lk-ttl{color:var(--t-primary);font-weight:700}
.m-man .lk-sec{font-weight:700;letter-spacing:.06em;margin:0}.m-man .lk-ind{padding-left:2.5ch}.m-man u{text-underline-offset:2px}.m-man .lk-card{border:0;border-left:0;background:transparent;padding:0}
.m-man .lk-foot{display:flex;justify-content:space-between;color:var(--t-muted);font-size:12px;border-top:1px solid var(--t-border);padding:4px 10px}
.m-blocks .lk-card{border-left:3px solid var(--t-accent,var(--t-border));padding:0}.m-blocks .lk-cmd{display:flex;justify-content:space-between;gap:8px;padding:6px 10px;border-bottom:1px solid var(--t-sel);color:var(--t-primary);font-weight:600}.m-blocks .lk-out{padding:6px 10px}
.m-prompt .lk-h::before{content:'crsp@home:~$ ';color:var(--t-primary);font-weight:400}
